-- ============================================================================
-- EC8: Gas Commercialisation & Gas Sales Agreements joins the catalogue in the
-- Economics & Commercial module. AN ENGINE COURSE: there is no Suite app; the
-- practicals run in the course's own calculator panels.
--
-- Catalogue row (module 'economics'; path_order 73; prereq_slug NULL,
-- the lead's decision; school left at its default) plus the three capstones and
-- their eighteen graded fields, generated by tools/course-waves/gsa/gen_course.py
-- from the ENGINE'S OWN RUN (gsa_capstone.mjs through the vendored
-- engines/economics/gasContract.js, petrolord-engines d745b88), which it
-- refuses to write unless fields.json carries exactly that run's values and the
-- tolerance gradedTolerance.js derives. Deep seeds are three separate
-- migrations; the go-live is a fifth and is HELD until a NextGen production
-- upload carries the route /dashboard/apps/gsa.
--
-- WHAT IS GRADED. OZUBU (Associate) grades a metered volume in MMBtu, a leap
-- year ACQ, the effective swing, a fortnight's buyer and seller shortfall and
-- one year's deficiency payment; IFEYI (Professional) grades an annual average
-- oil-indexed price, a deficiency payment, make-up taken and expired, the net
-- to the seller and a delivery obligation penalty; NWAKA (Expert) grades an
-- S-curve price, an annual average price, a carry-forward credit, the
-- end-of-term refund, an NPV and a gas royalty. Every value is a return value
-- of the engine, identical under every reading the engine states, independent
-- of the domestic base price, and the data it was run on is in the case file
-- the prompt names.
-- ============================================================================

insert into public.academy_apps (slug, name, module, path_order, status, prereq_slug)
values ('gsa', 'Gas Commercialisation & Gas Sales Agreements', 'economics', 73, 'coming_soon', null)
on conflict (slug) do nothing;

insert into public.academy_capstones
    (app_slug, tier, cert_tier, dataset, title, prompt, fields)
values
(
  'gsa', 'beginner', 'associate',
  'OZUBU, Ekene gas to the Ozubu Tile Works (synthetic)',
  'Quantities and one contract year',
  'OZUBU, Ekene gas to the Ozubu Tile Works (synthetic), an industrial buyer. One case file comes with this capstone: ozubu_case.json carries four calls under the keys energy, quantities, fortnight and year; paste it into the quantity calculator, whose views each read the key they need. The metered volume is 16.85 MMSm3 at a gross heating value of 38.62 MJ/Sm3. The DCQ is 22437.25 MMBtu per day, the 2028 contract year runs 2028-01-01 up to 2029-01-01, MaxDCQ is 115 percent and take-or-pay 85 percent. The fortnight in February 2029 carries a delivery tolerance of 150.5 MMBtu. The 2029 take-or-pay year states its reductions, its take and its prices in the case file, with make-up for 3 contract years taken only after the year''s Adjusted ACQ is taken (after-adjusted-acq). Every contract year states its permitted reduction (0 where the contract permits none). No value depends on any of the four readings the engine states, and no value uses the domestic base price or the price control of PIA s.167 (priceControlApplies): no call of this case prices gas under s.167 or s.168. Report six values: the metered volume in MMBtu; the ACQ of the 2028 contract year; the effective swing; the buyer shortfall and the seller shortfall over the fortnight; and the deficiency payment for 2029. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','ozubu_march_2028_mmbtu', 'label','The metered March 2028 volume in energy', 'unit','MMBtu', 'expected',616789.1475925302, 'tol',5e-07),
    jsonb_build_object('key','ozubu_2028_acq', 'label','The ACQ of the 2028 contract year', 'unit','MMBtu', 'expected',8212033.5, 'tol',5e-07),
    jsonb_build_object('key','ozubu_effective_swing', 'label','The effective swing', 'unit','ratio', 'expected',1.3529411764705883, 'tol',5e-07),
    jsonb_build_object('key','ozubu_fortnight_buyer_shortfall', 'label','The buyer shortfall over the fortnight', 'unit','MMBtu', 'expected',29797.125, 'tol',5e-07),
    jsonb_build_object('key','ozubu_fortnight_seller_shortfall', 'label','The seller shortfall over the fortnight', 'unit','MMBtu', 'expected',5546.5875000000015, 'tol',5e-07),
    jsonb_build_object('key','ozubu_2029_deficiency_payment', 'label','The deficiency payment for 2029', 'unit','USD', 'expected',2278799.7324424987, 'tol',5e-07)
  )
),
(
  'gsa', 'intermediate', 'professional',
  'IFEYI, Ekene gas to the Ifeyi Glass Cluster (synthetic), 2028 to 2033',
  'The ledger, the price and the Nigerian rules',
  'IFEYI, Ekene gas to the Ifeyi Glass Cluster (synthetic), 2028 to 2033. One case file comes with this capstone: ifeyi_case.json carries the price series and formula (price), the price basis of the ledger (pricing), the contract years (contract) and the lessee''s delivery obligation for 2031 (dgdo); paste it into the ledger calculator. The price is 0.62 + 0.0915 x the synthetic oil index in the case file, averaged over 3 months ending 1 month before the priced month, reset every 3 months from 2028-01, rounding model-gsa-4dp, floor 4.25 and ceiling 11.5, priced 2028-01 to 2033-12. Each year''s contract price is the annual average of its monthly prices (annual-average) and its take-or-pay price the annual average of its monthly prices (annual-average); make-up gas is invoiced at 0.35 US$ per MMBtu. Take-or-pay 82.5 percent of the Adjusted ACQ; make-up for 3 contract years, taken only after the year''s Adjusted ACQ is taken (after-adjusted-acq), the rest forfeited at the end of the term (forfeit). No carry-forward. The delivery obligation states voluntary contracts, two excuses and a signed agreement rate of 3.2 US$ per MMBtu. Every contract year states its permitted reduction (0 where the contract permits none). No value depends on any of the four readings the engine states, and no value uses the domestic base price or the price control of PIA s.167 (priceControlApplies): no call of this case prices gas under s.167 or s.168. Report six values: the annual average contract price of 2030; the deficiency payment for 2028; the make-up gas taken in 2031; the make-up that expires unrecovered at the end of 2031; the net to the seller over the term; and the delivery obligation penalty for 2031. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','ifeyi_2030_average_price', 'label','The annual average contract price of 2030', 'unit','USD/MMBtu', 'expected',7.601474999999998, 'tol',5e-07),
    jsonb_build_object('key','ifeyi_2028_deficiency_payment', 'label','The deficiency payment for 2028', 'unit','USD', 'expected',8156547.41985, 'tol',5e-07),
    jsonb_build_object('key','ifeyi_2031_make_up_taken', 'label','The make-up gas taken in 2031', 'unit','MMBtu', 'expected',656250.5, 'tol',5e-07),
    jsonb_build_object('key','ifeyi_2031_make_up_expired', 'label','The make-up that expires unrecovered at the end of 2031', 'unit','MMBtu', 'expected',253123.75, 'tol',5e-07),
    jsonb_build_object('key','ifeyi_total_net_to_seller', 'label','The net to the seller over the term', 'unit','USD', 'expected',451290197.49541664, 'tol',5e-07),
    jsonb_build_object('key','ifeyi_2031_dgdo_penalty', 'label','The Domestic Gas Delivery Obligation penalty for 2031', 'unit','USD', 'expected',2203738.7750000004, 'tol',5e-07)
  )
),
(
  'gsa', 'advanced', 'expert',
  'NWAKA, Ekene gas to the Nwaka Methanol Plant (synthetic), 2029 to 2035',
  'Parity, the whole contract and reading the engine',
  'NWAKA, Ekene gas to the Nwaka Methanol Plant (synthetic), 2029 to 2035. One case file comes with this capstone: nwaka_case.json carries the price series and formula (price), the price basis (pricing), the contract years (contract), the royalty terms (royalty), the discount rate and the base year; paste it into the contract calculator. The price is 0.45 + 0.118 x the synthetic oil index in the case file, averaged over 6 months ending 2 months before the priced month, reset every 3 months from 2029-01, rounding model-gsa-4dp, with an S-curve at 58 and 88 US$ per barrel, slope 0.059 below and 0.0472 above, priced 2029-01 to 2035-12. Each year''s contract price is the annual average of its monthly prices (annual-average) and its take-or-pay price its last month''s price (last-month); make-up gas is invoiced at 0.4 US$ per MMBtu. Take-or-pay 88 percent of the Adjusted ACQ; make-up for 3 contract years, taken only after the year''s take-or-pay quantity is taken (after-top-quantity), the rest refunded at the end of the term (refund). Carry-forward of takes above the take-or-pay quantity (top-quantity) for 2 contract years, at most 40 percent of a year''s deficiency. Royalty onshore, 100 percent of the gas utilised in-country; NPV at a discount rate of 0.1 to 2028, year-end flows. Every contract year states its permitted reduction (0 where the contract permits none). No value depends on any of the four readings the engine states, and no value uses the domestic base price or the price control of PIA s.167 (priceControlApplies): no call of this case prices gas under s.167 or s.168. Report six values: the contract price of July 2029; the annual average contract price of 2034; the carry-forward credit applied in 2030; the end-of-term refund in 2035; the NPV of the seller revenue; and the gas royalty in 2032. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','nwaka_july_2029_price', 'label','The contract price of July 2029', 'unit','USD/MMBtu', 'expected',7.1499, 'tol',5e-07),
    jsonb_build_object('key','nwaka_2034_average_price', 'label','The annual average contract price of 2034', 'unit','USD/MMBtu', 'expected',11.171475000000003, 'tol',5e-07),
    jsonb_build_object('key','nwaka_2030_carry_forward_credit', 'label','The carry-forward credit applied in 2030', 'unit','MMBtu', 'expected',479833.5, 'tol',5e-07),
    jsonb_build_object('key','nwaka_2035_refund', 'label','The end-of-term refund in 2035', 'unit','USD', 'expected',3403424.8770809956, 'tol',5e-07),
    jsonb_build_object('key','nwaka_npv_seller_revenue', 'label','The NPV of the seller revenue', 'unit','USD', 'expected',356188000.85156506, 'tol',5e-07),
    jsonb_build_object('key','nwaka_2032_royalty', 'label','The gas royalty in 2032', 'unit','USD', 'expected',2009337.8480662503, 'tol',5e-07)
  )
)
on conflict (app_slug, tier) do nothing;
